+1|// Stock market bubble chart + linked data table
+2|// Loads stock descriptions from CSV, renders a force-directed bubble chart
+3|// clustered by sector, and a synchronized table of all stocks.
+4|
+5|const SECTOR_ORDER = ["Information Technology", "Industry", "Energy", "Financial", "ETF"];
+6|const SECTOR_COLORS = {
+7|    "Information Technology": "#4e79a7",
+8|    "Industry":               "#f28e2b",
+9|    "Energy":                 "#e15759",
+10|    "Financial":              "#59a14f",
+11|    "ETF":                    "#9c6ade"
+12|};
+13|
+14|const WIDTH = 820;
+15|const HEIGHT = 620;
+16|const ETF_RADIUS = 22;
+17|
+18|function formatMarketCap(v) {
+19|    if (v == null || isNaN(v) || v === 0) return "—";
+20|    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
+21|    if (v >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
+22|    if (v >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
+23|    return d3.format(",")(Math.round(v));
+24|}
+25|
+26|d3.csv("data/stock-descriptions.csv").then(rawRows => {
+27|    const data = rawRows.map(r => {
+28|        const mc = r.marketCap ? +r.marketCap : null;
+29|        return {
+30|            ticker:    r.ticker,
+31|            sector:    r.sector,
+32|            name:      r["full name"],
+33|            marketCap: mc && !isNaN(mc) ? mc : null,
+34|            country:   r.country || "",
+35|            website:   r.website || "",
+36|            isETF:     r.sector === "ETF"
+37|        };
+38|    });
+39|
+40|    // Deterministic order: by sector (using SECTOR_ORDER), then market cap desc, then ticker
+41|    data.sort((a, b) => {
+42|        const sa = SECTOR_ORDER.indexOf(a.sector);
+43|        const sb = SECTOR_ORDER.indexOf(b.sector);
+44|        if (sa !== sb) return sa - sb;
+45|        const ma = a.marketCap ?? -1;
+46|        const mb = b.marketCap ?? -1;
+47|        if (mb !== ma) return mb - ma;
+48|        return d3.ascending(a.ticker, b.ticker);
+49|    });
+50|
+51|    renderBubbleChart(data);
+52|    renderTable(data);
+53|    renderLegend();
+54|});
+55|
+56|function renderLegend() {
+57|    const legend = d3.select("#legend");
+58|    SECTOR_ORDER.forEach(sector => {
+59|        const item = legend.append("div").attr("class", "legend-item");
+60|        item.append("span")
+61|            .attr("class", "legend-swatch")
+62|            .style("background", SECTOR_COLORS[sector]);
+63|        item.append("span").text(sector);
+64|    });
+65|}
+66|
+67|function renderBubbleChart(data) {
+68|    // Radius scale by market cap (sqrt → area is proportional)
+69|    const stocksWithCap = data.filter(d => d.marketCap);
+70|    const radiusScale = d3.scaleSqrt()
+71|        .domain(d3.extent(stocksWithCap, d => d.marketCap))
+72|        .range([14, 52]);
+73|
+74|    data.forEach(d => {
+75|        d.radius = d.isETF ? ETF_RADIUS : radiusScale(d.marketCap);
+76|    });
+77|
+78|    // Place sector centers in a pentagon around the chart middle so clusters
+79|    // stay close together and centered (not scattered to the edges).
+80|    const cx = WIDTH / 2;
+81|    const cy = HEIGHT / 2;
+82|    const clusterRadius = 150;
+83|    const sectorCenters = {};
+84|    SECTOR_ORDER.forEach((sector, i) => {
+85|        const angle = (i / SECTOR_ORDER.length) * 2 * Math.PI - Math.PI / 2;
+86|        sectorCenters[sector] = {
+87|            x: cx + clusterRadius * Math.cos(angle),
+88|            y: cy + clusterRadius * Math.sin(angle)
+89|        };
+90|    });
+91|
+92|    // Deterministic initial positions so layout is stable
+93|    data.forEach((d, i) => {
+94|        const c = sectorCenters[d.sector];
+95|        const a = (i * 137.5) * Math.PI / 180; // golden-angle spread
+96|        d.x = c.x + Math.cos(a) * 5;
+97|        d.y = c.y + Math.sin(a) * 5;
+98|    });
+99|
+100|    const svg = d3.select("#bubble-chart")
+101|        .append("svg")
+102|        .attr("viewBox", `0 0 ${WIDTH} ${HEIGHT}`)
+103|        .attr("preserveAspectRatio", "xMidYMid meet");
+104|
+105|    const nodeGroups = svg.selectAll("g.node")
+106|        .data(data, d => d.ticker)
+107|        .join("g")
+108|        .attr("class", "node")
+109|        .attr("data-ticker", d => d.ticker);
+110|
+111|    nodeGroups.append("circle")
+112|        .attr("class", "bubble")
+113|        .attr("r", d => d.radius)
+114|        .attr("fill", d => SECTOR_COLORS[d.sector])
+115|        .on("mouseover", function (event, d) {
+116|            if (d.isETF) return; // no tooltip for ETFs per spec
+117|            showTooltip(event, d);
+118|        })
+119|        .on("mousemove", function (event, d) {
+120|            if (d.isETF) return;
+121|            moveTooltip(event);
+122|        })
+123|        .on("mouseout", hideTooltip)
+124|        .on("click", function (event, d) {
+125|            selectStock(d.ticker);
+126|        });
+127|
+128|    nodeGroups.append("text")
+129|        .attr("class", "bubble-label")
+130|        .style("font-size", d => Math.max(9, Math.min(14, d.radius / 2.2)) + "px")
+131|        .text(d => d.ticker);
+132|
+133|    const simulation = d3.forceSimulation(data)
+134|        .force("x",       d3.forceX(d => sectorCenters[d.sector].x).strength(0.18))
+135|        .force("y",       d3.forceY(d => sectorCenters[d.sector].y).strength(0.18))
+136|        .force("charge",  d3.forceManyBody().strength(2))
+137|        .force("collide", d3.forceCollide(d => d.radius + 1.5).strength(1))
+138|        .alphaDecay(0.028)
+139|        .on("tick", () => {
+140|            nodeGroups.attr("transform", d => {
+141|                // Keep bubbles inside the chart area
+142|                d.x = Math.max(d.radius, Math.min(WIDTH  - d.radius, d.x));
+143|                d.y = Math.max(d.radius, Math.min(HEIGHT - d.radius, d.y));
+144|                return `translate(${d.x},${d.y})`;
+145|            });
+146|        });
+147|
+148|    // Store for cross-highlighting
+149|    window._bubbleNodes = nodeGroups;
+150|    window._simulation  = simulation;
+151|}
+152|
+153|function renderTable(data) {
+154|    const table = d3.select("#table-container").append("table");
+155|    table.append("thead").append("tr").selectAll("th")
+156|        .data(["Ticker symbol", "Full company name", "Sector", "Market cap"])
+157|        .join("th")
+158|        .text(d => d);
+159|
+160|    const rows = table.append("tbody").selectAll("tr")
+161|        .data(data, d => d.ticker)
+162|        .join("tr")
+163|        .attr("data-ticker", d => d.ticker)
+164|        .on("click", function (event, d) {
+165|            selectStock(d.ticker);
+166|            this.scrollIntoView({ block: "nearest", behavior: "smooth" });
+167|        });
+168|
+169|    rows.append("td").attr("class", "ticker-cell").text(d => d.ticker);
+170|    rows.append("td").text(d => d.name);
+171|    rows.append("td").append("span")
+172|        .attr("class", "sector-chip")
+173|        .style("background", d => SECTOR_COLORS[d.sector])
+174|        .text(d => d.sector);
+175|    rows.append("td").attr("class", "marketcap-cell").text(d => formatMarketCap(d.marketCap));
+176|
+177|    window._tableRows = rows;
+178|}
+179|
+180|function selectStock(ticker) {
+181|    window._bubbleNodes.select("circle")
+182|        .classed("selected", d => d.ticker === ticker);
+183|    window._tableRows
+184|        .classed("selected", d => d.ticker === ticker);
+185|
+186|    // Scroll table row into view
+187|    const selectedRow = document.querySelector(`tr[data-ticker="${ticker}"]`);
+188|    if (selectedRow) {
+189|        selectedRow.scrollIntoView({ block: "nearest", behavior: "smooth" });
+190|    }
+191|}
+192|
+193|// --- Tooltip helpers -------------------------------------------------------
+194|const tooltip = d3.select("#tooltip");
+195|
+196|function showTooltip(event, d) {
+197|    const html = `
+198|        <div class="tooltip-title">${d.ticker}</div>
+199|        <div class="tooltip-row"><span class="tooltip-label">Name</span><span>${d.name}</span></div>
+200|        <div class="tooltip-row"><span class="tooltip-label">Sector</span><span>${d.sector}</span></div>
+201|    `;
+202|    tooltip.classed("visible", true).html(html);
+203|    moveTooltip(event);
+204|}
+205|
+206|function moveTooltip(event) {
+207|    tooltip
+208|        .style("left", (event.pageX + 14) + "px")
+209|        .style("top",  (event.pageY + 14) + "px");
+210|}
+211|
+212|function hideTooltip() {
+213|    tooltip.classed("visible", false);
+214|}
+215|
